import React, { useState, useEffect } from 'react';
import { FaLeaf, FaShoppingCart, FaUser, FaBars, FaTimes } from 'react-icons/fa';

const Navbar = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const scrollToSection = (sectionId) => {
    const section = document.getElementById(sectionId);
    if (section) {
      section.scrollIntoView({ behavior: 'smooth' });
      setIsMenuOpen(false);
    }
  };

  const navItems = [
    { id: 'home', label: 'Home' },
    { id: 'about', label: 'About' },
    { id: 'marketplace', label: 'Marketplace' },
    { id: 'contact', label: 'Contact' },
  ];

  return (
    <>
      <nav className={`navbar ${scrolled ? 'scrolled' : ''}`}>
        <div className="container">
          <div className="nav-container">
            {/* Brand Logo */}
            <div className="brand" onClick={() => scrollToSection('home')}>
              <FaLeaf className="logo-icon" />
              <div className="logo-text">
                <span className="logo-primary">FreshFarm</span>
                <span className="logo-subtitle">Direct from Farm</span>
              </div>
            </div>

            {/* Desktop Navigation */}
            <div className="nav-desktop">
              <ul className="nav-list">
                {navItems.map((item) => (
                  <li key={item.id} className="nav-item">
                    <button
                      className="nav-link"
                      onClick={() => scrollToSection(item.id)}
                    >
                      {item.label}
                    </button>
                  </li>
                ))}
              </ul>
            </div>

            {/* Desktop Actions */}
            <div className="nav-actions">
              <button className="action-btn cart-btn">
                <FaShoppingCart />
                <span className="cart-count">3</span>
              </button>
              <button className="action-btn user-btn">
                <FaUser />
                <span>Account</span>
              </button>
              <button className="cta-btn" onClick={() => scrollToSection('marketplace')}>
                Shop Now
              </button>
            </div>

            {/* Mobile Menu Button */}
            <button className="mobile-toggle" onClick={toggleMenu}>
              {isMenuOpen ? <FaTimes /> : <FaBars />}
            </button>
          </div>
        </div>
      </nav>

      {/* Mobile Menu */}
      {isMenuOpen && (
        <div className="mobile-menu-overlay" onClick={toggleMenu}>
          <div className="mobile-menu" onClick={e => e.stopPropagation()}>
            <div className="mobile-menu-header">
              <div className="mobile-brand">
                <FaLeaf />
                <span>FreshFarm</span>
              </div>
              <button className="mobile-close" onClick={toggleMenu}>
                <FaTimes />
              </button>
            </div>

            <div className="mobile-menu-content">
              <ul className="mobile-nav-list">
                {navItems.map((item) => (
                  <li key={item.id}>
                    <button
                      className="mobile-nav-link"
                      onClick={() => scrollToSection(item.id)}
                    >
                      {item.label}
                    </button>
                  </li>
                ))}
              </ul>

              <div className="mobile-actions">
                <button className="mobile-action-btn">
                  <FaShoppingCart />
                  <span>Cart (3)</span>
                </button>
                <button className="mobile-action-btn">
                  <FaUser />
                  <span>My Account</span>
                </button>
                <button className="mobile-cta-btn" onClick={() => scrollToSection('marketplace')}>
                  Shop Fresh Produce
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <style jsx>{`
        /* Navbar Styles */
        .navbar {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          z-index: 1000;
          padding: 1rem 0;
          transition: all 0.4s ease;
          background: rgba(255, 255, 255, 0.95);
          backdrop-filter: blur(10px);
          border-bottom: 1px solid rgba(229, 231, 235, 0.8);
        }

        .navbar.scrolled {
          padding: 0.5rem 0;
          box-shadow: 0 5px 20px rgba(0, 0, 0, 0.1);
          background: rgba(255, 255, 255, 0.98);
        }

        .nav-container {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 2rem;
        }

        /* Brand */
        .brand {
          display: flex;
          align-items: center;
          gap: 0.75rem;
          cursor: pointer;
          padding: 0.5rem;
          border-radius: 12px;
          transition: all 0.3s ease;
